// BulkUpdateIssues is the resolver for the bulkUpdateIssues field.
func (r *mutationResolver) BulkUpdateIssues(ctx context.Context, input generated.BulkUpdateIssuesInput, clientID *uuid.UUID, opID *uuid.UUID) (*generated.BulkIssuePayload, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	in := domain.BulkUpdateIssuesInput{
		IDs:           input.Ids,
		StateID:       input.StateID,
		AssigneeID:    input.AssigneeID,
		ClearAssignee: deref(input.ClearAssignee),
		Priority:      input.Priority,
		Estimate:      input.Estimate,
		ClearEstimate: deref(input.ClearEstimate),
		DueDate:       toDate(input.DueDate),
		ClearDueDate:  deref(input.ClearDueDate),
	}

	type bulkResult struct {
		issues  []model.Issue
		skipped []domain.BulkSkip
	}
	// Wrapped so the whole batch replays as one recorded result. Replaying it as N
	// separate keys would let a retry after a partial response apply half the batch twice.
	result, version, err := idempotent(ctx, r.Svc, p, clientID, opID, in,
		func(ctx context.Context) (bulkResult, int64, error) {
			issues, skipped, version, err := r.Svc.BulkUpdateIssues(ctx, p, in)
			return bulkResult{issues, skipped}, version, err
		})
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	issues, err := r.hydrateIssues(ctx, p, selectionFor(ctx, "BulkIssuePayload").childOrNone("issues", "Issue"), result.issues)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	return &generated.BulkIssuePayload{
		Version: int(version),
		Issues:  issues,
		Skipped: toBulkSkips(result.skipped),
	}, nil
}

