// InviteToWorkspace is the resolver for the inviteToWorkspace field.
func (r *mutationResolver) InviteToWorkspace(ctx context.Context, input generated.InviteInput) (*generated.InvitePayload, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	role := "member"
	if input.Role != nil {
		role, err = fromUserRole(*input.Role)
		if err != nil {
			return nil, PresentError(ctx, err)
		}
	}

	created, err := r.Svc.InviteToWorkspace(ctx, p, domain.InviteInput{
		Email:   input.Email,
		Role:    role,
		TeamIDs: input.TeamIds,
	})
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	outRole, err := toUserRole(created.Role)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	// The token travels back once and is not stored in a readable form, so a caller that
	// loses this response has to re-invite. That is the intended outcome: the alternative
	// is a table of live invitation links anybody with database access can walk.
	return &generated.InvitePayload{
		ID:        created.ID,
		Email:     created.Email,
		Role:      outRole,
		ExpiresAt: created.ExpiresAt,
		Token:     created.Token,
	}, nil
}

