// Team is the resolver for the team field.
//
// Answered from the same permission-filtered list Query.teams returns. A lookup with its
// own visibility check would eventually disagree with the list, and the disagreement that
// matters is the one where the lookup is more generous.
func (r *queryResolver) Team(ctx context.Context, id uuid.UUID) (*generated.Team, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	teams, err := r.loaders(ctx).allTeams(ctx, p)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	team, ok := teams.byID[id]
	if !ok {
		// Not-found rather than forbidden: confirming that a private team, or a team in
		// somebody else's workspace, exists is itself the leak.
		return nil, PresentError(ctx, platform.NotFound("team"))
	}

	out, err := r.hydrateTeam(ctx, p, selectionFor(ctx, "Team"), team)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	return &out, nil
}

// TeamByKey is the resolver for the teamByKey field.
func (r *queryResolver) TeamByKey(ctx context.Context, key string) (*generated.Team, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	teams, err := r.loaders(ctx).allTeams(ctx, p)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	// Keys are stored upper-case and appear in URLs, where people type them in whatever
	// case they like.
	want := strings.ToUpper(strings.TrimSpace(key))
	for _, t := range teams.all {
		if t.Key != want {
			continue
		}
		out, err := r.hydrateTeam(ctx, p, selectionFor(ctx, "Team"), t)
		if err != nil {
			return nil, PresentError(ctx, err)
		}
		return &out, nil
	}
	return nil, PresentError(ctx, platform.NotFound("team"))
}

