// IssueByIdentifier is the resolver for the issueByIdentifier field.
//
// The identifier is what people paste into chat and type into the URL bar, so this is the
// deep-link path. It resolves against the team's live issues, which means an archived one
// is reachable by id and not by identifier — the same distinction the client makes, since
// archived issues are never part of its replica.
func (r *queryResolver) IssueByIdentifier(ctx context.Context, identifier string) (*generated.Issue, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	key, number, err := parseIdentifier(identifier)
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	teams, err := r.loaders(ctx).allTeams(ctx, p)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	var teamID uuid.UUID
	for _, t := range teams.all {
		if t.Key == key {
			teamID = t.ID
			break
		}
	}
	if teamID == uuid.Nil {
		// An unknown prefix and an unreadable team give the same answer, so the identifier
		// cannot be used to probe for teams the caller may not see.
		return nil, PresentError(ctx, platform.NotFound("issue"))
	}

	issues, err := r.Svc.ListIssuesForTeam(ctx, p, teamID)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	for _, i := range issues {
		if i.Number != number {
			continue
		}
		out, err := r.hydrateIssue(ctx, p, selectionFor(ctx, "Issue"), i)
		if err != nil {
			return nil, PresentError(ctx, err)
		}
		return &out, nil
	}
	return nil, PresentError(ctx, platform.NotFound("issue"))
}

