// Search is the resolver for the search field.
func (r *queryResolver) Search(ctx context.Context, input generated.SearchInput) (*generated.SearchResults, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	results, err := r.Svc.Search(ctx, p, domain.SearchInput{
		Query:           input.Query,
		Filter:          input.Filter,
		TeamID:          input.TeamID,
		First:           deref(input.First),
		IncludeArchived: deref(input.IncludeArchived),
	})
	if err != nil {
		return nil, PresentError(ctx, err)
	}

	issues, err := r.hydrateIssues(ctx, p, selectionFor(ctx, "SearchResults").childOrNone("issues", "Issue"), results.Issues)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	comments, err := r.hydrateComments(ctx, p, selectionFor(ctx, "SearchResults").childOrNone("comments", "Comment"), results.Comments)
	if err != nil {
		return nil, PresentError(ctx, err)
	}
	return &generated.SearchResults{
		Issues:     issues,
		Comments:   comments,
		IssueCount: results.IssueCount,
	}, nil
}

